 */
int clockevents_program_event(struct clock_event_device *dev, ktime_t expires, bool force)
{
	int64_t delta;
	u64 cycles;

	if (WARN_ON_ONCE(expires < 0))
		return -ETIME;

	dev->next_event = expires;

	if (clockevent_state_shutdown(dev))
		return 0;

